package com.tihai.utils;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import okhttp3.*;import static org.junit.jupiter.api.Assertions.*;
class HomeworkRetakeTest {
 @TempDir Path temp;
 static final String URL="https://mooc1.chaoxing.com/mooc-ans/mooc2/work/view?courseId=2&classId=3&cpi=4&workId=5&answerId=6";
 static String reviewed(String answer){return "<input id=courseId value=2><input id=classId value=3><input id=cpi value=4><input id=workId value=5><input id=answerId value=6><div class=fanyaMarking><span class=resultNum>80分</span><a class=redo onclick='redoWork()'>重做</a><div class=singleQuesId data=1><h3 class=mark_name>1. (单选题) Example</h3><ul><li>A. Alpha</li><li>B. Beta</li></ul><span>正确答案:<span class=rightAnswerContent>"+answer+"</span></span><span class=myAnswer>我的答案:A</span></div></div><script>function redoWork(){var redoTimes=5+0-1;var url='/work/phone/redo';location.href='/mooc-ans/mooc2/work/dowork?courseId=2&classId=3&cpi=4&workId=5&answerId=6&enc=fixture';}</script>";}
 static Map<String,Object> current(String options){Map<String,Object> q=new LinkedHashMap<>();q.put("id","99");q.put("title","(单选题) Example");q.put("type","single");q.put("options",options);q.put("needsVision",false);return q;}
 @Test void modernCompletedAssignmentRecognizedAndOnlyPublishedAnswersUsed()throws Exception{Map<String,Object> p=HomeworkRetake.read(reviewed("B"),URL);assertEquals(1,p.get("available"));assertEquals(4,p.get("remaining"));assertTrue(HomeworkRetake.submitted(reviewed("B")));assertEquals(true,QuizPageReader.read(reviewed("B")).get("alreadySubmitted"));List<Map<String,Object>> qs=(List<Map<String,Object>>)p.get("questions");assertEquals("B",qs.get(0).get("canonicalAnswer"));assertTrue(HomeworkRetake.editableUrl(reviewed("B"),URL).contains("enc=fixture"));Request r=HomeworkRetake.reset(reviewed("B"),URL);assertEquals("6",r.url().queryParameter("workAnswerId"));assertEquals("/mooc-ans/work/phone/redo",r.url().encodedPath());}
 @Test void reorderedOptionsAndChangedIdsMappedByContent()throws Exception{List<Map<String,Object>> qs=(List<Map<String,Object>>)HomeworkRetake.read(reviewed("B"),URL).get("questions");Map<String,Object> q=current("A. Beta\nB. Alpha");HomeworkRetake.match(qs,Arrays.asList(q));assertEquals("A",q.get("answer"));assertEquals("平台公布答案",q.get("answerSource"));}
 @Test void missingOfficialAnswerNeverFallsBackToOwnAnswer()throws Exception{Map<String,Object> p=HomeworkRetake.read(reviewed(""),URL);assertEquals(0,p.get("available"));assertThrows(java.io.IOException.class,()->HomeworkRetake.complete(p));assertThrows(java.io.IOException.class,()->HomeworkRetake.reset(reviewed(""),URL));}
 @Test void changedOrAmbiguousQuestionsStopBeforeResetSubmission()throws Exception{List<Map<String,Object>> qs=(List<Map<String,Object>>)HomeworkRetake.read(reviewed("B"),URL).get("questions");assertThrows(java.io.IOException.class,()->HomeworkRetake.match(qs,Arrays.asList(current("A. Other\nB. Alpha"))));Map<String,Object> q=current("A. Alpha\nB. Beta");q.put("title","different");assertThrows(java.io.IOException.class,()->HomeworkRetake.match(qs,Arrays.asList(q)));}
 @Test void exhaustedOrHiddenRetakeAndForeignIdentityRejected()throws Exception{assertThrows(java.io.IOException.class,()->HomeworkRetake.reset(reviewed("B").replace("5+0-1","0+0-0"),URL));assertThrows(java.io.IOException.class,()->HomeworkRetake.reset(reviewed("B").replace("class=redo","class=none"),URL));assertThrows(java.io.IOException.class,()->HomeworkRetake.reset(reviewed("B"),URL.replace("workId=5","workId=7")));assertThrows(java.io.IOException.class,()->HomeworkRetake.editableUrl(reviewed("B").replace("enc=fixture","enc=fixture").replace("location.href='/mooc-ans","location.href='https://example.org/mooc-ans"),URL));}
 @Test void publishedAnswersSurviveRestartSeparatelyFromMainLibrary()throws Exception{HomeworkRetake store=new HomeworkRetake(temp);Map<String,Object> p=HomeworkRetake.read(reviewed("B"),URL);store.save("work",p);Map<String,Object> restored=new HomeworkRetake(temp).load("work");assertEquals(1,restored.get("available"));assertNull(store.load("other"));}
 @Test void modernMultipleChoiceLabelsPreserved()throws Exception{String html="<form id=submitForm method=post><input name=answertype99 value=1><div class=singleQuesId data=99><h3 class=mark_name>(多选题) Example</h3><div class=stem_answer><div class=answerBg><span class=num_option_dx>A</span><div class=answer_p>Alpha</div></div><div class=answerBg><span class=num_option_dx>B</span><div class=answer_p>Beta</div></div></div></div></form>";List<Map<String,Object>> qs=(List<Map<String,Object>>)QuizPageReader.read(html).get("questions");assertEquals("A. Alpha\nB. Beta",qs.get(0).get("options"));assertEquals(Arrays.asList("A. Alpha","B. Beta"),ReviewParser.read(html).get(0).get("options"));}
 @Test void optionParagraphsRemainOneChoice()throws Exception{Map<String,Object> q=current("A. First line\ncontinued text\nB. Second choice");assertEquals(2,AssignmentDraft.options(q).size());assertTrue(AssignmentDraft.options(q).get(0).contains("continued text"));}
 @Test void finalSubmitFillsJsQuestionIdsAndClearsSaveOnlyFlag()throws Exception{String html="<form id=submitForm method=post action='/mooc-ans/work/addStudentWorkNewWeb'><input type=hidden name=pyFlag value=1><input type=hidden name=questionIds value=''><input name=answertype99 value=0><div class=singleQuesId data=99><h3 class=mark_name>Example</h3><ul><li>A. Alpha</li><li>B. Beta</li></ul></div></form>";Map<String,Object> page=QuizPageReader.read(html);List<Map<String,Object>> qs=(List<Map<String,Object>>)page.get("questions");qs.get(0).put("answer","B");FormBody body=(FormBody)AssignmentDraft.request(html,URL,page,qs).body();Map<String,String> fields=new HashMap<>();for(int i=0;i<body.size();i++)fields.put(body.name(i),body.value(i));assertEquals("99,",fields.get("questionIds"));assertEquals("",fields.get("pyFlag"));assertEquals("B",fields.get("answer99"));}
}
